function decode(x: number): bigint {
	if (x === 0) return 0n;
	const b = Buffer.alloc(8);
	b.writeDoubleBE(x);
	const value = b.readBigUInt64BE(),
		field = value >> 52n;
	return field === 0n ? value : ((value & 0xfffffffffffffn) + 0x10000000000000n) << (field - 1n);
}

export function plainMoments(amounts: readonly number[]) {
	const anchor = decode(amounts[0]),
		n = BigInt(amounts.length);
	let sum = 0n,
		sumSquares = 0n;
	for (const x of amounts) {
		const delta = decode(x) - anchor;
		sum += delta;
		sumSquares += delta * delta;
	}
	const dispersion = n * sumSquares - sum * sum;
	const delta = n * (decode(amounts[amounts.length - 1]) - anchor) - sum;
	// Scale leading bits only for an approximate root; the exact cell check decides acceptance.
	const numerator = delta * delta * (n - 1n),
		denominator = n * dispersion;
	return {
		numerator: numerator.toString(),
		denominator: denominator.toString(),
		negative: delta < 0n,
	};
}

export function plainNumbers(amounts: readonly number[], dailyAverage: number) {
	return {
		zScore: plainScore(plainMoments(amounts)),
		dailyRatio:
			amounts[amounts.length - 1] === 0
				? 0
				: amounts[amounts.length - 1] / Math.max(dailyAverage, 1),
	};
}

export function plainScore(moments: ReturnType<typeof plainMoments>): number {
	const numerator = BigInt(moments.numerator),
		denominator = BigInt(moments.denominator);
	let magnitude = 0;
	if (numerator !== 0n && denominator !== 0n) {
		const shiftN = Math.max(0, numerator.toString(2).length - 53);
		const shiftD = Math.max(0, denominator.toString(2).length - 53);
		const power = shiftN - shiftD;
		const estimate =
			Math.sqrt(
				(Number(numerator >> BigInt(shiftN)) / Number(denominator >> BigInt(shiftD))) *
					2 ** (power % 2),
			) *
			2 ** Math.floor(power / 2);
		magnitude = roundRoot(numerator, denominator, estimate);
	}
	return magnitude === 0 ? 0 : moments.negative ? -magnitude : magnitude;
}

function raw(x: number): bigint {
	const b = Buffer.alloc(8);
	b.writeDoubleBE(x);
	return b.readBigUInt64BE();
}

function roundRoot(n: bigint, d: bigint, candidate: number): number {
	if (n === 0n) return 0;
	// Try a Number candidate, then its immediate neighbors. Exact midpoint tests certify each cell.
	const center = raw(candidate);
	const compare = (sumUnits: bigint) => d * sumUnits ** 2n - n * (2n * denominatorUnit) ** 2n;
	for (const bits of [center, center - 1n, center + 1n]) {
		if (bits < 0n || bits > 0x7fefffffffffffffn) continue;
		const here = decode(value(bits));
		const low = bits === 0n ? -1n : compare(here + decode(value(bits - 1n)));
		const high = compare(here + decode(value(bits + 1n)));
		if (
			(low < 0n || (low === 0n && bits % 2n === 0n)) &&
			(high > 0n || (high === 0n && bits % 2n === 0n))
		)
			return value(bits);
	}
	// Certify a bracket in the known finite score range (|z| < 8 for n <= 64).
	let lo = 0n,
		hi = raw(8);
	while (lo + 1n < hi) {
		const mid = (lo + hi) >> 1n,
			u = decode(value(mid));
		if (d * u * u <= n * denominatorUnit * denominatorUnit) lo = mid;
		else hi = mid;
	}
	const cmp = compare(decode(value(lo)) + decode(value(hi)));
	return value(cmp < 0n || (cmp === 0n && lo % 2n !== 0n) ? hi : lo);
}

function value(bits: bigint): number {
	const b = Buffer.alloc(8);
	b.writeBigUInt64BE(bits);
	return b.readDoubleBE();
}

constructor(readonly binding: SpendingBinding) {
		this.binding = referenceBinding(binding);
	}

evidenceSnapshot() {
		return [...this.evidenceRecords.values()].filter((v) => {
			const domain = this.identity.get(v.occurrence.revisionDomain);
			return (
				domain &&
				equal(domain.get(v.occurrence.revision)?.occurrence ?? null, v.occurrence) &&
				[...domain.keys()].filter((n) => n <= v.occurrence.revision).length ===
					v.occurrence.revision
			);
		});
	}

invalidate(lane: PlainLane) {
		if (lane === "pack" || lane === "arrivals") this.eligible.clear();
		if (lane === "pack") this.pack = undefined;
		else if (lane === "arrivals") this.pending.length = 0;
		else delete this.facts[lane];
	}

obligationSnapshot() {
		const evidence = this.evidenceSnapshot();
		return [...this.watermarks].map(([domain, through]) => {
			const rows = [...(this.identity.get(domain)?.values() ?? [])].filter(
				(e) => e.occurrence.revision <= through,
			);
			const sequence =
				rows.length === through &&
				rows.every((e) => this.occurrenceAdmissions.has(e.evaluationRef));
			const lifecycle =
				sequence &&
				![...this.pendingTerminals.values()].some((t) => {
					const ref = this.evaluations.get(t.id)!.occurrence;
					return ref.revisionDomain === domain && ref.revision <= through;
				}) &&
				![...this.pendingOutcomes.values()].some(
					(o) => o.occurrence.revisionDomain === domain && o.occurrence.revision <= through,
				) &&
				rows.every((e) => {
					const effect = this.effects.get(e.evaluationRef);
					return (
						this.released.has(e.evaluationRef) &&
						this.branches.get(e.evaluationRef)?.size === 3 &&
						(!effect || effect.admission?.state === "rejected" || !!effect.outcome)
					);
				});
			const retainedEvidence =
				lifecycle &&
				rows.every((e) =>
					["spending-input", "spending-code-binding", "spending-verification"].every((kind) =>
						evidence.some((v) => equal(v.occurrence, e.occurrence) && v.evidenceKind === kind),
					),
				);
			return {
				revisionDomain: domain,
				evaluatedThroughRevision: through,
				lifecycle,
				retainedEvidence,
			};
		});
	}

private prepare(lane: PlainLane, raw: unknown): unknown {
		const v = referenceInput<any>(lane, raw, this.binding);
		if (lane === "verification")
			for (const receipt of v.receipts) {
				const key = canonical(receipt.receiptRef),
					prior = this.receiptHistory.get(key),
					content = canonical(receipt);
				if (prior !== undefined && prior !== content) this.receiptConflicts.add(key);
				if (this.receiptConflicts.has(key)) throw Error("receipt conflict");
				if (prior === undefined && this.receiptHistory.size >= 64) throw Error("receipt capacity");
				this.receiptHistory.set(key, content);
			}
		return v;
	}

push(lane: PlainLane, raw: unknown) {
		const arrived: string[] = [];
		let value: unknown;
		try {
			value = this.prepare(lane, raw);
		} catch (e) {
			if (lane === "pack") this.pack = undefined;
			else if (lane === "arrivals") this.pending.length = 0;
			else delete this.facts[lane];
			if (lane === "pack" || lane === "arrivals") this.eligible.clear();
			this.issues.push(String(e));
			return;
		}
		if (lane === "pack") {
			const pack = value as EvaluationPack,
				text = canonical(pack, 4 * 1048576);
			if (this.packText !== undefined && text !== this.packText) {
				this.pack = undefined;
				this.eligible.clear();
				this.issues.push("pack conflict");
				return;
			}
			this.pack = pack;
			this.packText = text;
		} else if (lane === "arrivals") {
			for (const ref of (value as ArrivalFrame).evaluationRefs) {
				if (this.pending.length >= 64) {
					this.issues.push("pending capacity");
					break;
				}
				this.pending.push(ref);
			}
		} else {
			Object.assign(this.facts, { [lane]: value });
			if (lane === "current")
				for (const c of (value as CurrentFrame).current) {
					const prior = this.watermarks.get(c.revisionDomain) ?? 0;
					if (this.retainDomain(c.revisionDomain) && c.watermark >= prior)
						this.watermarks.set(c.revisionDomain, c.watermark);
				}
		}
		if (this.pack) {
			for (const id of this.pending.splice(0)) {
				const e = this.pack.evaluations.find((e) => e.evaluationRef === id);
				if (!e) {
					this.issues.push("unknown evaluation");
					continue;
				}
				this.eligible.add(id);
				arrived.push(id);
				if (this.evaluations.has(id)) continue;
				this.evaluations.set(id, e);
				const { occurrence, ...body } = e,
					{ digest: claimed, ...coordinates } = occurrence;
				if (
					this.retainDomain(occurrence.revisionDomain) &&
					claimed ===
						digest({
							schemaRevision: "graphrefly/causal-occurrence-contract/v1@contract-v2",
							...coordinates,
							value: body,
						})
				) {
					let domain = this.identity.get(occurrence.revisionDomain);
					if (!domain) {
						domain = new Map();
						this.identity.set(occurrence.revisionDomain, domain);
					}
					if (!domain.has(occurrence.revision)) domain.set(occurrence.revision, e);
				}
				const result = plainBusiness(e);
				if (this.retainDomain(e.occurrence.revisionDomain)) this.branches.set(id, new Set());
				this.assessments.set(id, result);
				if (!result.flagged) continue;
				try {
					if (this.materials.size >= 64) throw Error("material capacity");
					const material = plainMaterial(e, this.binding, result);
					const { runRef: _run, evidenceMode: _mode, ...profile } = this.binding;
					oracleSnapshot(profile, [...this.materials.values(), material]);
					this.materials.set(id, material);
					this.effects.set(id, {
						proposal: {
							occurrence: e.occurrence,
							effectId: material.body.effectId,
							requestRef: material.requestRef,
							proposalDigest: material.proposalDigest,
						},
					});
				} catch (error) {
					this.issues.push(String(error));
				}
			}
		}
		if (lane === "verification")
			for (const receipt of (value as VerificationFrame).receipts) {
				const key = canonical(receipt.receiptRef);
				if (!this.evidenceReceipts.has(key) && this.evidenceReceipts.size < 64)
					this.evidenceReceipts.set(key, receipt);
			}
		this.reconcile(lane === "inbox" ? (value as InboxObservationFrame).outcomes : [], arrived);
	}

private reconcile(incomingOutcomes: readonly CausalEffectOutcome[], arrived: readonly string[]) {
		const { current, verification, local, inbox } = this.facts;
		// Admission and contiguous watermark release are sticky authority facts. A pending
		// proposal remains retained independently of whether it is visible as a released effect.
		for (const id of this.eligible) {
			const e = this.evaluations.get(id)!;
			if (
				current?.current.some(
					(c) =>
						equal(c.occurrence, e.occurrence) &&
						equal(c.policyRef, e.policyRef) &&
						c.policyDigest === e.policyDigest,
				)
			)
				if (this.retainDomain(e.occurrence.revisionDomain)) this.occurrenceAdmissions.add(id);
		}
		for (const [name, domain] of this.identity) {
			const through = this.watermarks.get(name);
			if (through === undefined) continue;
			const ordered = [...domain].filter(([n]) => n <= through).sort(([a], [b]) => a - b);
			if (
				ordered.length !== through ||
				ordered.some(([n, e], i) => n !== i + 1 || !this.occurrenceAdmissions.has(e.evaluationRef))
			)
				continue;
			const latest = new Map<string, Evaluation>();
			for (const [, e] of ordered) latest.set(e.occurrence.occurrenceId, e);
			for (const e of latest.values()) this.released.add(e.evaluationRef);
		}
		for (const [key, { id, branch }] of this.pendingTerminals) {
			const occurrence = this.evaluations.get(id)!.occurrence;
			const retained = this.identity.get(occurrence.revisionDomain)?.get(occurrence.revision);
			if (retained && !equal(retained.occurrence, occurrence)) {
				this.pendingTerminals.delete(key);
				continue;
			}
			if (this.released.has(id)) {
				this.branches.get(id)?.add(branch);
				this.pendingTerminals.delete(key);
			}
		}
		for (const branch of ["assessment", "explanation"])
			for (const id of arrived) this.terminal(id, branch);
		for (const [id, record] of this.effects) {
			if (record.admission || !this.eligible.has(id)) continue;
			const e = this.evaluations.get(id)!,
				material = this.materials.get(id)!;
			const receipts =
				verification?.receipts.filter(
					(v) =>
						equal(v.occurrence, e.occurrence) &&
						v.inputDigest === e.inputDigest &&
						v.policyDigest === e.policyDigest &&
						v.sourceDigest === this.binding.sourceDigest &&
						v.runtimeDigest === this.binding.runtimeDigest &&
						v.requestDigest === material.body.payloadDigest &&
						v.verifierRevision === "spending-oracle-v2" &&
						v.numericDomainRef === "spending-finite-v1",
				) ?? [];
			if (receipts.length !== 1 || receipts[0].verdict === "unavailable") continue;
			const receipt = receipts[0];
			if (receipt.verdict === "fail") {
				record.admission = {
					...record.proposal,
					state: "rejected",
					admissionRef: {
						kind: "spending-admission",
						id: digest({
							proposal: record.proposal,
							receiptRef: receipt.receiptRef,
							verdict: "fail",
							binding: this.binding,
						}),
					},
				};
				continue;
			}
			if (!current || !local || !inbox) continue;
			if (
				!current.current.some(
					(c) =>
						equal(c.occurrence, e.occurrence) &&
						equal(c.policyRef, e.policyRef) &&
						c.policyDigest === e.policyDigest &&
						c.watermark >= e.occurrence.revision,
				)
			)
				continue;
			const grants = local.grants.filter(
				(g) =>
					equal(g.occurrence, e.occurrence) &&
					g.requestDigest === material.body.payloadDigest &&
					equal(g.destinationRef, this.binding.destinationRef) &&
					g.hostEpoch === this.binding.hostEpoch &&
					g.replayScope.hostEpoch === this.binding.hostEpoch &&
					g.replayScope.compositionEpoch === this.binding.compositionEpoch,
			);
			if (grants.length !== 1) continue;
			const g = grants[0],
				refused =
					g.revoked || local.stop || local.tick < g.validFrom || local.tick > g.validThrough;
			if (
				!refused &&
				(!inbox.readiness.ready ||
					inbox.readiness.availableSlots !== 1 ||
					local.tick < inbox.readiness.observedAt ||
					local.tick > inbox.readiness.validThrough)
			)
				continue;
			record.admission = {
				...record.proposal,
				state: refused ? "rejected" : "admitted",
				admissionRef: {
					kind: "spending-admission",
					id: digest({
						proposal: record.proposal,
						receiptRef: receipt.receiptRef,
						grantRef: g.grantRef,
						binding: this.binding,
					}),
				},
			};
		}
		const applyOutcome = (o: CausalEffectOutcome): boolean => {
			const e = [...this.effects.values()].find(
				(e) => equal(e.proposal.occurrence, o.occurrence) && e.proposal.effectId === o.effectId,
			);
			if (
				!e?.admission ||
				![...this.effects].some(([id, record]) => record === e && this.released.has(id))
			)
				return false;
			if (
				e.admission.state === "admitted" &&
				equal(e.proposal.requestRef, o.requestRef) &&
				e.proposal.proposalDigest === o.proposalDigest &&
				equal(e.admission.admissionRef, o.admissionRef) &&
				!e.outcome
			)
				e.outcome = o;
			// A known admission makes mismatches definitive; don't let them block a later exact item.
			// The first exact outcome (including unknown) remains immutable.
			return true;
		};
		for (const [key, o] of this.pendingOutcomes)
			if (applyOutcome(o)) this.pendingOutcomes.delete(key);
		for (const o of incomingOutcomes) {
			const result = o.result;
			if (!result || typeof result !== "object") continue;
			if (o.state === "succeeded") {
				if (result.kind !== "ok" || !Object.hasOwn(result, "value")) continue;
			} else {
				if (!["failed", "cancelled", "unknown", "reconcile-required"].includes(o.state)) continue;
				if (
					result.kind !== "error" ||
					!result.error ||
					result.error.kind !== "issue" ||
					typeof result.error.code !== "string" ||
					!result.error.code ||
					typeof result.error.message !== "string" ||
					!result.error.message
				)
					continue;
			}
			if (!this.retainDomain(o.occurrence.revisionDomain)) continue;
			const key = digest({ occurrence: o.occurrence, effectId: o.effectId });
			if (!applyOutcome(o) && !this.pendingOutcomes.has(key) && this.pendingOutcomes.size < 64)
				this.pendingOutcomes.set(key, o);
		}

		for (const id of this.eligible) {
			const e = this.evaluations.get(id)!,
				b = this.assessments.get(id)!;
			if (!this.domains.has(e.occurrence.revisionDomain)) continue;
			if (
				(!b.flagged || this.effects.get(id)?.admission || !this.materials.has(id)) &&
				!this.issuedPolicy.has(id)
			) {
				this.issuedPolicy.add(id);
				this.terminal(id, "publication-policy");
			}
			const retain = (v: CausalEvidence) => {
				const key = canonical([v.occurrence, v.evidenceKind, v.evidenceId]);
				if (!this.evidenceRecords.has(key) && this.evidenceRecords.size < 512)
					this.evidenceRecords.set(key, v);
			};
			for (const [kind, value] of [
				["spending-input", e.inputDigest],
				[
					"spending-code-binding",
					digest({
						sourceDigest: this.binding.sourceDigest,
						runtimeDigest: this.binding.runtimeDigest,
					}),
				],
			])
				retain({
					occurrence: e.occurrence,
					evidenceKind: kind,
					evidenceId: `${id}:${kind}`,
					evidenceDigest: value,
					coverage: "included",
					refs: [this.binding.runRef],
				});
			const request = b.flagged
				? this.materials.get(id)?.body.payloadDigest
				: digest({ kind: "no-publish", evaluationRef: id });
			for (const receipt of this.evidenceReceipts.values())
				if (equal(receipt.occurrence, e.occurrence)) {
					const stale =
						receipt.sourceDigest !== this.binding.sourceDigest ||
						receipt.runtimeDigest !== this.binding.runtimeDigest ||
						receipt.inputDigest !== e.inputDigest ||
						receipt.policyDigest !== e.policyDigest ||
						receipt.verifierRevision !== "spending-oracle-v2" ||
						receipt.numericDomainRef !== "spending-finite-v1" ||
						(request !== undefined && receipt.requestDigest !== request);
					retain({
						occurrence: e.occurrence,
						evidenceKind: "spending-verification",
						evidenceId: digest(receipt.receiptRef),
						evidenceDigest: digest(receipt),
						coverage: stale
							? "stale"
							: receipt.verdict === "unavailable" || request === undefined
								? "unavailable"
								: "included",
						refs: [receipt.artifactRef.id],
					});
				}
		}
	}

applyOutcome = (o: CausalEffectOutcome): boolean => {
			const e = [...this.effects.values()].find(
				(e) => equal(e.proposal.occurrence, o.occurrence) && e.proposal.effectId === o.effectId,
			);
			if (
				!e?.admission ||
				![...this.effects].some(([id, record]) => record === e && this.released.has(id))
			)
				return false;
			if (
				e.admission.state === "admitted" &&
				equal(e.proposal.requestRef, o.requestRef) &&
				e.proposal.proposalDigest === o.proposalDigest &&
				equal(e.admission.admissionRef, o.admissionRef) &&
				!e.outcome
			)
				e.outcome = o;
			// A known admission makes mismatches definitive; don't let them block a later exact item.
			// The first exact outcome (including unknown) remains immutable.
			return true;
		}

retain = (v: CausalEvidence) => {
				const key = canonical([v.occurrence, v.evidenceKind, v.evidenceId]);
				if (!this.evidenceRecords.has(key) && this.evidenceRecords.size < 512)
					this.evidenceRecords.set(key, v);
			}

private retainDomain(domain: string) {
		if (this.domains.has(domain)) return true;
		if (this.domains.size === 64) {
			this.issues.push("domain capacity");
			return false;
		}
		this.domains.add(domain);
		return true;
	}

snapshot() {
		return [...this.effects]
			.filter(([id]) => this.released.has(id))
			.map(([, e]) => ({
				proposal: e.proposal,
				admission: e.admission ?? null,
				outcome: e.outcome ?? null,
			}));
	}

private terminal(id: string, branch: string) {
		const e = this.evaluations.get(id)!;
		if (!this.retainDomain(e.occurrence.revisionDomain)) return;
		const retained = this.identity.get(e.occurrence.revisionDomain)?.get(e.occurrence.revision);
		if (retained && !equal(retained.occurrence, e.occurrence)) return;
		if (this.released.has(id)) {
			this.branches.get(id)?.add(branch);
			return;
		}
		const key = canonical([id, branch]);
		if (!this.pendingTerminals.has(key) && this.pendingTerminals.size < 64)
			this.pendingTerminals.set(key, { id, branch });
	}

export function plainBusiness(e: Evaluation) {
	const txn = e.prefix[e.prefix.length - 1];
	const { zScore, dailyRatio } = plainNumbers(
		e.prefix.map((t) => t.amount),
		e.profile.dailyAverage,
	);
	const factors: string[] = [];
	if (zScore > e.policy.zThreshold)
		factors.push(`Amount is ${zScore.toFixed(2)}σ above this vendor's historical mean.`);
	if (dailyRatio > e.policy.dailyRatioThreshold)
		factors.push(`Amount is ${dailyRatio.toFixed(1)}× the user's daily average.`);
	if (!e.profile.typicalCategories.includes(txn.category))
		factors.push("Category is outside the user's typical spend profile.");
	const severity = factors.length >= 3 ? "high" : factors.length === 2 ? "medium" : "low",
		flagged = factors.length > 0;
	const message = flagged
		? `Transaction ${txn.id} flagged — severity: ${severity}.\nVendor: ${txn.vendor}  Amount: $${txn.amount.toFixed(2)}  Category: ${txn.category}\nReasoning:\n${factors.map((f) => `  • ${f}`).join("\n")}`
		: `Transaction ${txn.id} ($${txn.amount.toFixed(2)} at ${txn.vendor}) — normal.`;
	return {
		score: {
			zScore,
			dailyRatio,
			categoryFamiliarity: e.profile.typicalCategories.includes(txn.category) ? "known" : "unknown",
			txn,
		},
		flagged,
		reason: { factors, severity, txn },
		message,
	};
}

export function plainMaterial(e: Evaluation, b: SpendingBinding, result: PlainBusiness) {
	const payloadText = canonical({
		transactionId: result.score.txn.id,
		vendor: result.score.txn.vendor,
		severity: result.reason.severity,
		message: result.message,
	});
	if (Buffer.byteLength(payloadText) + 1 > 4096) throw Error("payload capacity");
	return oracleMaterial({
		schema: "spending-alerts/request-material/v1" as const,
		occurrence: e.occurrence,
		effectId: `alert:${e.evaluationRef}`,
		inputDigest: e.inputDigest,
		policyDigest: e.policyDigest,
		payloadText,
		payloadDigest: oracleHash(payloadText),
		sourceDigest: b.sourceDigest,
		runtimeDigest: b.runtimeDigest,
		destinationRef: b.destinationRef,
		compositionEpoch: b.compositionEpoch,
		hostEpoch: b.hostEpoch,
	});
}

bool: Check = (v) => {
	if (typeof v !== "boolean") reject();
}

current: Check = (v) => {
	fields(v, {
		revisionDomain: text(),
		occurrence,
		policyRef: ref,
		policyDigest: digest,
		watermark: number(),
	});
	if (v.revisionDomain !== v.occurrence.revisionDomain) reject();
}

digest: Check = (v) => {
	if (typeof v !== "string" || !/^sha256:[a-f0-9]{64}$/.test(v)) reject();
}

evaluation: Check = (e) => {
	fields(e, {
		evaluationRef: text(),
		subjectRef: text(),
		occurrence,
		inputDigest: digest,
		profileRef: ref,
		profile,
		policyRef: ref,
		policyDigest: digest,
		policy,
		prefix: list(transaction, 64, 1),
	});
	unique(e.prefix.map((t: any) => t.id));
	if (
		new Set(e.prefix.map((t: any) => t.vendor)).size !== 1 ||
		Buffer.byteLength(canonical(e)) > 65536
	)
		reject();
	if (
		e.inputDigest !==
			oracleHash(canonical({ profileRef: e.profileRef, profile: e.profile, prefix: e.prefix })) ||
		e.policyDigest !== oracleHash(canonical(e.policy))
	)
		reject();
}

fields = (value: any, shape: Record<string, Check>) => {
	if (
		!value ||
		Array.isArray(value) ||
		typeof value !== "object" ||
		Object.keys(value).sort().join() !== Object.keys(shape).sort().join()
	)
		reject();
	for (const key of Object.keys(shape)) shape[key](value[key]);
}

grant: Check = (v) => {
	fields(v, {
		grantRef: ref,
		ownerRef: ref,
		operation: literal("append-alert"),
		occurrence,
		requestDigest: digest,
		destinationRef: ref,
		hostEpoch: number(undefined, 1),
		validFrom: number(),
		validThrough: number(),
		maxWrites: number(64, 1),
		replayScope: (x) =>
			fields(x, { compositionEpoch: number(undefined, 1), hostEpoch: number(undefined, 1) }),
		revoked: bool,
	});
	if (v.validFrom > v.validThrough) reject();
}

list =
	(check: Check, max = 64, min = 0): Check =>
	(v) => {
		if (!Array.isArray(v) || v.length < min || v.length > max) reject();
		for (let i = 0; i < v.length; i++) {
			if (!Object.hasOwn(v, i)) reject();
			check(v[i]);
		}
	}

literal =
	(...values: unknown[]): Check =>
	(v) => {
		if (!values.includes(v)) reject();
	}

number =
	(max = Number.MAX_SAFE_INTEGER, min = 0, integer = true): Check =>
	(v) => {
		if (
			typeof v !== "number" ||
			!Number.isFinite(v) ||
			v < min ||
			v > max ||
			(integer && !Number.isSafeInteger(v))
		)
			reject();
	}

outcome: Check = (v) =>
	fields(v, {
		occurrence,
		effectId: text(),
		requestRef: ref,
		admissionRef: ref,
		proposalDigest: digest,
		state: literal("succeeded", "failed", "cancelled", "unknown", "reconcile-required"),
		result: (x) => {
			if (!x || typeof x !== "object" || !["ok", "error"].includes(x.kind)) reject();
		},
	})

export function referenceBinding(raw: unknown): SpendingBinding {
	const value = JSON.parse(canonical(raw));
	binding(value);
	return oracleFreeze(value);
}

export function referenceInput<T>(lane: ReferenceLane, raw: unknown, expected: SpendingBinding): T {
	const encoded = canonical(raw, lane === "pack" ? 4 * 1048576 : 1048576);
	if (Buffer.byteLength(encoded) > (lane === "pack" ? 4 * 1048576 : 1048576)) reject();
	const v = JSON.parse(encoded);
	if (lane === "arrivals") {
		fields(v, { packRef: ref, evaluationRefs: list(text()) });
		if (canonical(v.packRef) !== canonical(expected.packRef)) reject();
	} else {
		const shape: Record<Exclude<ReferenceLane, "arrivals">, Record<string, Check>> = {
			pack: { format: literal("spending-input-v1"), evaluations: list(evaluation) },
			current: { current: list(current) },
			verification: { receipts: list(receipt) },
			local: { tick: number(), stop: bool, grants: list(grant) },
			inbox: {
				issuerRef: ref,
				artifactRef: ref,
				artifactDigest: digest,
				readiness: (x) =>
					fields(x, {
						ready: bool,
						observedAt: number(),
						validThrough: number(),
						availableSlots: number(1),
					}),
				outcomes: list(outcome),
			},
		};
		fields(v, { binding, ...shape[lane] });
		if (canonical(v.binding) !== canonical(expected)) reject();
		if (lane === "pack") {
			unique(v.evaluations.map((e: any) => e.evaluationRef));
			unique(v.evaluations.map((e: any) => e.occurrence));
			if (new Set(v.evaluations.map((e: any) => e.prefix[0].vendor)).size > 2) reject();
			const domains = new Map<string, string>();
			for (const e of v.evaluations) {
				const vendor = e.prefix[0].vendor,
					prior = domains.get(e.occurrence.revisionDomain);
				if (prior !== undefined && prior !== vendor) reject();
				domains.set(e.occurrence.revisionDomain, vendor);
			}
		} else if (lane === "current") unique(v.current.map((c: any) => c.revisionDomain));
	}
	return oracleFreeze(v);
}

reject = () => {
	throw new TypeError("reference input contract");
}

text =
	(limit = 128): Check =>
	(v) => {
		if (typeof v !== "string" || !v.length || Buffer.byteLength(v) > limit) reject();
	}

transaction: Check = (v) => {
	fields(v, {
		id: text(),
		vendor: text(256),
		category: text(256),
		amount: number(1e9, 0, false),
		timestampIso: text(),
	});
	if (
		!/^\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d\.\d{3}Z$/.test(v.timestampIso) ||
		!Number.isFinite(Date.parse(v.timestampIso)) ||
		new Date(v.timestampIso).toISOString() !== v.timestampIso
	)
		reject();
}

unique = (items: unknown[]) => {
	if (new Set(items.map((x) => canonical(x))).size !== items.length) reject();
}

#clear(lane: PlainHostLane) {
		if (lane === "pack") this.#pack = undefined;
		else if (lane === "current") this.#current = undefined;
		else if (lane === "verification") this.#verification = undefined;
		else if (lane === "local") this.#local = undefined;
	}

#complete(record: MutableRecord, state: CausalEffectOutcome["state"], code: string): void {
		if (record.outcome) return;
		const result =
			state === "succeeded"
				? { kind: "ok" as const, value: { source: "plain-host-result" } }
				: {
						kind: "error" as const,
						error: { kind: "issue" as const, code: `spending-host/${code}`, message: code },
					};
		canonical(result, 4096);
		record.outcome = freeze({
			...proposal(record.request),
			admissionRef: record.admission.admissionRef,
			state,
			result,
		});
		if (state === "unknown" || state === "reconcile-required") this.#unknown = true;
		this.#revision++;
		this.#schedule();
	}

#dispatch(): void {
		for (const effect of this.#plain.snapshot()) {
			const admission = effect.admission;
			if (!admission || admission.state !== "admitted" || effect.outcome) continue;
			const request = [...this.#plain.materials.values()].find((m) =>
				equal(proposal(m), effect.proposal),
			);
			if (
				!request ||
				!equal(
					{ ...proposal(request), admissionRef: admission.admissionRef, state: "admitted" },
					admission,
				)
			)
				continue;
			const body = request.body;
			if (
				body.hostEpoch !== this.binding.hostEpoch ||
				body.compositionEpoch !== this.binding.compositionEpoch ||
				body.sourceDigest !== this.binding.sourceDigest ||
				body.runtimeDigest !== this.binding.runtimeDigest ||
				!equal(body.destinationRef, this.binding.destinationRef)
			)
				continue;
			const key = canonical(effect.proposal),
				prior = this.#records.get(key);
			if (prior) {
				if (!equal(prior.admission, admission)) this.#fault = "admission-conflict";
				continue;
			}
			if (this.#fault) continue;
			if (this.#records.size >= 64) {
				this.#fault = "record-capacity-proof-failed";
				continue;
			}
			const record: MutableRecord = {
				request: freeze(JSON.parse(canonical(request))),
				admission: freeze(JSON.parse(canonical(admission))),
			};
			this.#records.set(key, record);
			const current =
				this.#current?.current.filter((c) => equal(c.occurrence, body.occurrence)) ?? [];
			const receipts =
				this.#verification?.receipts.filter(
					(r) =>
						equal(r.occurrence, body.occurrence) &&
						r.inputDigest === body.inputDigest &&
						r.policyDigest === body.policyDigest &&
						r.sourceDigest === body.sourceDigest &&
						r.runtimeDigest === body.runtimeDigest &&
						r.requestDigest === body.payloadDigest &&
						r.verifierRevision === "spending-oracle-v2" &&
						r.numericDomainRef === "spending-finite-v1",
				) ?? [];
			const grants =
				this.#local?.grants.filter(
					(g) =>
						equal(g.occurrence, body.occurrence) &&
						g.requestDigest === body.payloadDigest &&
						equal(g.destinationRef, body.destinationRef) &&
						g.hostEpoch === body.hostEpoch &&
						g.replayScope.compositionEpoch === body.compositionEpoch &&
						g.replayScope.hostEpoch === body.hostEpoch,
				) ?? [];
			const evaluation = this.#pack?.evaluations.find((e) => equal(e.occurrence, body.occurrence));
			const local = this.#local,
				receipt = receipts[0],
				grant = grants[0],
				inbox = this.#inbox;
			const denied =
				!local ||
				local.stop ||
				current.length !== 1 ||
				current[0].policyDigest !== body.policyDigest ||
				current[0].watermark < body.occurrence.revision ||
				!evaluation ||
				!equal(current[0].policyRef, evaluation.policyRef) ||
				receipts.length !== 1 ||
				receipt.verdict !== "pass" ||
				this.#plain.receiptConflicts.has(canonical(receipt.receiptRef)) ||
				grants.length !== 1 ||
				grant.revoked ||
				admission.admissionRef.kind !== "spending-admission" ||
				admission.admissionRef.id !==
					digest({
						proposal: effect.proposal,
						receiptRef: receipt.receiptRef,
						grantRef: grant.grantRef,
						binding: this.binding,
					}) ||
				local.tick < grant.validFrom ||
				local.tick > grant.validThrough ||
				!inbox ||
				!inbox.readiness.ready ||
				inbox.readiness.availableSlots !== 1 ||
				local.tick < inbox.readiness.observedAt ||
				local.tick > inbox.readiness.validThrough;
			if (denied) {
				this.#complete(record, "cancelled", "final-guard");
				continue;
			}
			if (this.#unknown || this.#inFlight !== 0 || this.#writes >= Math.min(64, grant.maxWrites)) {
				this.#complete(record, "cancelled", "busy-or-write-budget");
				continue;
			}
			const payload = body.payloadText + "\n";
			if (Buffer.byteLength(payload) > 4096) {
				this.#complete(record, "cancelled", "payload-capacity");
				continue;
			}
			this.#inFlight++;
			this.#revision++;
			this.#schedule();
			if (this.#fault) {
				this.#inFlight--;
				this.#complete(record, "cancelled", "notification-unavailable");
				continue;
			}
			this.#writes++;
			try {
				Promise.resolve(this.write(payload)).then(
					(result) => {
						this.#inFlight--;
						let state: CausalEffectOutcome["state"] = "unknown";
						try {
							const descriptor = Object.getOwnPropertyDescriptor(result, "bytesWritten");
							if (
								descriptor &&
								"value" in descriptor &&
								descriptor.value === Buffer.byteLength(payload)
							)
								state = "succeeded";
						} catch {
							/* Malformed result cannot establish success. */
						}
						this.#complete(record, state, "short-or-unknown-write");
					},
					() => {
						this.#inFlight--;
						this.#complete(record, "unknown", "write-rejected");
					},
				);
			} catch {
				this.#inFlight--;
				this.#complete(record, "unknown", "write-threw");
			}
		}
	}

#frame(): InboxObservationFrame {
		const ready = !this.#fault && !this.#unknown && this.#inFlight === 0 && this.#records.size < 64;
		return freeze({
			binding: this.binding,
			issuerRef: { kind: "fixture", id: "owned-offline-host" },
			artifactRef: { kind: "fixture-artifact", id: "simulated-writes" },
			artifactDigest: digest("offline-host-not-real-io"),
			readiness: {
				ready,
				observedAt: 0,
				validThrough: Number.MAX_SAFE_INTEGER,
				availableSlots: ready ? 1 : 0,
			},
			outcomes: [...this.#records.values()].flatMap((r) => (r.outcome ? [r.outcome] : [])),
		});
	}

#publish(): void {
		if (!this.#listeners.size) return;
		try {
			const value = this.observations();
			for (const listener of [...this.#listeners]) listener(value);
		} catch {
			this.#fault = "delivery-failed";
		}
	}

#schedule(): void {
		if (this.#scheduled || this.#delivering || this.#fault) return;
		this.#scheduled = true;
		try {
			queueMicrotask(() => {
				this.#scheduled = false;
				this.#delivering = true;
				const captured = this.#revision;
				try {
					const frame = this.#frame();
					this.#maxFrameBytes = Math.max(this.#maxFrameBytes, Buffer.byteLength(canonical(frame)));
					this.#notifications++;
					this.#inbox = frame;
					this.#plain.push("inbox", frame);
					this.#dispatch();
					this.#publish();
				} catch {
					this.#fault = "delivery-failed";
				} finally {
					this.#delivering = false;
				}
				if (!this.#fault && captured !== this.#revision) this.#schedule();
			});
		} catch {
			this.#scheduled = false;
			this.#fault = "schedule-failed";
		}
	}

constructor(
		binding: SpendingBinding,
		private readonly write: (payload: string) => Promise<{ readonly bytesWritten: number }>,
	) {
		this.binding = referenceBinding(binding);
		this.#plain = new PlainSpending(this.binding);
		this.#revision++;
		this.#schedule();
		Object.freeze(this);
	}

feed(lane: PlainHostLane, value: unknown): void {
		this.feedMany([{ lane, value }]);
	}

feedMany(steps: readonly PlainHostStep[]): void {
		for (const { lane, value } of steps) {
			if (!["pack", "current", "verification", "local", "arrivals"].includes(lane))
				throw new TypeError("plain host input lane");
			let safe: unknown;
			try {
				safe = referenceInput(lane, value, this.binding);
				if (lane === "pack") {
					const text = canonical(safe, 4 * 1048576);
					if (this.#packText !== undefined && this.#packText !== text)
						throw new TypeError("plain host pack conflict");
					this.#packText = text;
					this.#pack = safe as EvaluationPack;
				} else if (lane === "current") this.#current = safe as CurrentFrame;
				else if (lane === "verification") this.#verification = safe as VerificationFrame;
				else if (lane === "local") this.#local = safe as LocalAuthorityFrame;
			} catch {
				this.#clear(lane);
			}
			// The plain coordinator performs its own input validation and retains its own issue facts.
			this.#plain.push(lane, safe ?? null);
			if (
				lane === "verification" &&
				this.#verification?.receipts.some((receipt) => {
					const key = canonical(receipt.receiptRef);
					return (
						this.#plain.receiptConflicts.has(key) ||
						this.#plain.receiptHistory.get(key) !== canonical(receipt)
					);
				})
			)
				this.#verification = undefined;
		}
		this.#dispatch();
		this.#publish();
	}

inspect() {
		const obligations = this.#plain.obligationSnapshot();
		const frontier =
			!!this.#pack &&
			this.#pack.evaluations.every((e) =>
				obligations.some(
					(o) =>
						o.revisionDomain === e.occurrence.revisionDomain &&
						o.evaluatedThroughRevision >= e.occurrence.revision,
				),
			);
		const settled = this.#plain
			.snapshot()
			.every(
				(e) =>
					e.admission?.state === "rejected" ||
					(e.outcome !== null && !["unknown", "reconcile-required"].includes(e.outcome.state)),
			);
		const normalEndReady =
			!this.#fault &&
			!this.#unknown &&
			this.#inFlight === 0 &&
			!this.#scheduled &&
			!this.#delivering &&
			!!this.#local?.stop &&
			frontier &&
			obligations.length > 0 &&
			obligations.every((o) => o.lifecycle && o.retainedEvidence) &&
			settled;
		return Object.freeze({
			records: Object.freeze([...this.#records.values()].map((r) => freeze({ ...r }))),
			writes: this.#writes,
			inFlight: this.#inFlight,
			fault: this.#fault,
			unknown: this.#unknown,
			dispatchStopped: this.#unknown || this.#fault !== undefined,
			normalEndReady,
			scheduled: this.#scheduled,
			delivering: this.#delivering,
			notifications: this.#notifications,
			maxFrameBytes: this.#maxFrameBytes,
		});
	}

invalidate(lane: PlainHostLane): void {
		if (!["pack", "current", "verification", "local", "arrivals"].includes(lane))
			throw new TypeError("plain host input lane");
		this.#clear(lane);
		this.#plain.invalidate(lane);
		this.#dispatch();
		this.#publish();
	}

observations(): PlainHostObservation {
		return freeze(
			JSON.parse(
				canonical({
					effects: this.#plain.snapshot(),
					assessments: [...this.#plain.assessments],
					materials: [...this.#plain.materials],
					evidence: this.#plain.evidenceSnapshot(),
					obligations: this.#plain.obligationSnapshot(),
					issues: this.#plain.issues,
				}),
			),
		);
	}

observe(
		listener: (observation: ReturnType<PlainSpendingProofHost["observations"]>) => void,
	): () => void {
		this.#listeners.add(listener);
		try {
			listener(this.observations());
		} catch (error) {
			this.#listeners.delete(listener);
			throw error;
		}
		return () => {
			this.#listeners.delete(listener);
		};
	}

proposal = (request: PlainHostRecord["request"]): CausalEffectProposal => ({
	occurrence: request.body.occurrence,
	effectId: request.body.effectId,
	requestRef: request.requestRef,
	proposalDigest: request.proposalDigest,
})

export function oracleCanonical(input: unknown, maxBytes = 1048576): string {
	return oracleEncoding(input, maxBytes).text;
}

function oracleEncoding(input: unknown, maxBytes = 1048576) {
	let remaining = maxBytes,
		immutable = true;
	const active = new Set<object>();
	function charge(text: string) {
		remaining -= Buffer.byteLength(text);
		if (remaining < 0) throw Error("frame bound");
		return text;
	}
	function string(value: string) {
		if (value.length > remaining) throw Error("frame bound");
		for (let i = 0; i < value.length; i++) {
			const c = value.charCodeAt(i);
			if (c >= 0xd800 && c <= 0xdbff) {
				const next = value.charCodeAt(++i);
				if (!(next >= 0xdc00 && next <= 0xdfff)) throw Error("surrogate");
			} else if (c >= 0xdc00 && c <= 0xdfff) throw Error("surrogate");
		}
		return charge(JSON.stringify(value));
	}
	function encode(value: unknown): string {
		if (value === null || typeof value === "boolean") return charge(JSON.stringify(value));
		if (typeof value === "number" && Number.isFinite(value)) return charge(JSON.stringify(value));
		if (typeof value === "string") return string(value);
		if (typeof value !== "object" || value === null || active.has(value)) throw Error("passive");
		const array = Array.isArray(value),
			proto = Object.getPrototypeOf(value);
		if (array ? proto !== Array.prototype : proto !== Object.prototype && proto !== null)
			throw Error("prototype");
		if (array && value.length > remaining / 2) throw Error("array bound");
		const keys = Reflect.ownKeys(value);
		if (keys.length > remaining / 2 || keys.some((k) => typeof k !== "string")) throw Error("keys");
		const names = (keys as string[]).filter((k) => !array || k !== "length");
		if (array && (names.length !== value.length || names.some((k, i) => k !== String(i))))
			throw Error("array");
		active.add(value);
		immutable &&= Object.isFrozen(value);
		const encoded: string[] = [charge(array ? "[" : "{")];
		let first = true;
		for (const key of array ? names : names.sort()) {
			const d = Object.getOwnPropertyDescriptor(value, key)!;
			if (!("value" in d) || !d.enumerable) throw Error("descriptor");
			if (!first) encoded.push(charge(","));
			first = false;
			if (!array) encoded.push(string(key), charge(":"));
			encoded.push(encode(d.value));
		}
		encoded.push(charge(array ? "]" : "}"));
		active.delete(value);
		return encoded.join("");
	}
	return {
		text: encode(input),
		get immutable() {
			return immutable;
		},
	};
}

